// === Tab: CombCircle ===
class CombinedCircle {
	constructor(x, y, r, a, da, child = null) {
		this.x = x;
		this.y = y;
		this.r = r;
		this.a = a;
		this.da = da;
		this.child = child;

		this.pts = [];
		this.calcPt();
	}

	update() {
		this.a += this.da;
		this.calcPt();

		if (this.child) {
			this.child.update();
		}
	}

	setPos(x, y) {
		this.x = x;
		this.y = y;
	}

	calcPt() {
		const dx = cos(this.a) * this.r;
		const dy = sin(this.a) * this.r;
		this.px = this.x + dx;
		this.py = this.y + dy;
		this.xx = this.px;
		this.yy = this.py;

		if (this.child) {
			this.child.setPos(this.px, this.py);
			this.child.calcPt();
			this.xx = this.child.xx;
			this.yy = this.child.yy;
		}

		this.pts.unshift({x: this.xx - this.x, y: this.yy - this.y});
		this.pts.splice(width, 100);
	}

	show(details = false) {
		strokeWeight(1);
		stroke("rgba(255,192,203,0.25)")
		circle(this.x, this.y, this.r * 2);
		line(this.x, this.y, this.px, this.py);

		if (this.child) this.child.show();

		if (details) {
			strokeWeight(3);
			const c1 = color("rgba(255,192,203,0.75)");
			const c2 = color("rgba(255,20,147,0.75)");
			beginShape();
			// vertex(this.xx, this.yy);
			// vertex(this.x + this.r, this.yy);
			for (let i = 0; i < this.pts.length; i++) {
				stroke(lerpColor(c1, c2, i/this.pts.length));
				vertex(this.x + i-i + this.pts[i].x, this.y + this.pts[i].y);
			}
			endShape();
		}
	}
}

