let ccirc;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("");
	frameRate(60);

	stroke(212);
	strokeWeight(2);
	noFill();

	let lastCirc = null;
	for (let i = 0; i < 9; i++) {
		ccirc = new CombinedCircle(width/2, height/2, ~~random(50, 150), 0, random(0.01, 0.1) * Math.sign(random(-1, 1)), lastCirc);
		lastCirc = ccirc;
	}
}

function draw() {
	background(4, 4, 12);

	ccirc.update();
	ccirc.show(true);
}

function mouseClicked() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width * 0.1) setup();
}
